<template>
  <div class="report-view bg-light min-vh-100">
    <NavBarVue />

    <b-container fluid class="py-4">
      <b-row class="justify-content-center">
        <b-col lg="11">
          <b-card no-body class="border-0 shadow-sm mb-4">
            <b-card-body class="p-4">
              <b-row align-v="center">
                <b-col lg="4" class="mb-3 mb-lg-0">
                  <h4 class="text-dark font-weight-bold mb-1">
                    <b-icon
                      icon="journal-text"
                      class="text-mbr-green mr-2"
                    ></b-icon>
                    Logs do Sistema
                  </h4>
                  <p class="text-muted small mb-0">
                    Rastreio de atividades e segurança
                  </p>
                </b-col>

                <b-col lg="8">
                  <b-row class="align-items-end justify-content-end">
                    <b-col sm="4">
                      <label class="small font-weight-bold text-secondary"
                        >Início</label
                      >
                      <b-form-datepicker
                        v-model="fromDate"
                        size="sm"
                        local="pt-PT"
                        placeholder="Data inicial"
                        class="border-0 bg-light"
                        today-button
                        reset-button
                      ></b-form-datepicker>
                    </b-col>
                    <b-col sm="4">
                      <label class="small font-weight-bold text-secondary"
                        >Fim</label
                      >
                      <b-form-datepicker
                        v-model="toDate"
                        size="sm"
                        local="pt-PT"
                        placeholder="Data final"
                        class="border-0 bg-light"
                        today-button
                        reset-button
                      ></b-form-datepicker>
                    </b-col>
                    <b-col sm="auto" class="mt-2 mt-sm-0">
                      <b-button
                        variant="mbr-green"
                        @click="getSystemLogs()"
                        :disabled="isLoading"
                        size="sm"
                        class="px-4 shadow-sm"
                      >
                        <b-icon
                          icon="search"
                          v-if="!isLoading"
                          class="mr-1"
                        ></b-icon>
                        <b-spinner small v-else></b-spinner>
                        Pesquisar
                      </b-button>
                    </b-col>
                  </b-row>
                </b-col>
              </b-row>
            </b-card-body>
          </b-card>

          <b-card no-body class="border-0 shadow-sm overflow-hidden">
            <b-card-header
              class="bg-white border-0 py-3 d-flex justify-content-between align-items-center"
            >
              <h6 class="mb-0 font-weight-bold text-muted">
                Registos encontrados: <b class="text-dark">{{ logs.length }}</b>
              </h6>
              <b-button-group size="sm">
                <b-button
                  variant="outline-danger"
                  @click="downloadSystemLogsPDF()"
                >
                  <b-icon icon="file-earmark-pdf-fill"></b-icon> PDF
                </b-button>
                <b-button
                  variant="outline-success"
                  @click="downloadSystemLogsExcel()"
                >
                  <b-icon icon="file-earmark-excel-fill"></b-icon> Excel
                </b-button>
              </b-button-group>
            </b-card-header>

            <b-overlay :show="isLoading" rounded="sm" opacity="0.6">
              <div class="table-responsive">
                <table class="table table-hover mb-0">
                  <thead
                    class="bg-mbr-light text-mbr-green small text-uppercase font-weight-bold"
                  >
                    <tr>
                      <th class="border-0 pl-4">Data e Hora</th>
                      <th class="border-0">Utilizador</th>
                      <th class="border-0">Operação</th>
                      <th class="border-0">Detalhes da Atividade</th>
                    </tr>
                  </thead>
                  <tbody class="text-secondary">
                    <tr v-for="log in logs" :key="log.id">
                      <td class="pl-4 align-middle">
                        <div class="d-flex flex-column">
                          <span class="text-dark font-weight-bold">{{
                            formatDate(log.createdAt)
                          }}</span>
                          <small class="text-muted">{{
                            formatTime(log.createdAt)
                          }}</small>
                        </div>
                      </td>
                      <td class="align-middle">
                        <div class="d-flex align-items-center">
                          <b-avatar
                            size="1.4rem"
                            variant="light"
                            class="mr-2"
                          ></b-avatar>
                          <span class="font-weight-500">{{
                            log.userName
                          }}</span>
                        </div>
                      </td>
                      <td class="align-middle">
                        <b-badge
                          :variant="getActionVariant(log.action)"
                          pill
                          class="px-3 py-1"
                        >
                          {{ log.action }}
                        </b-badge>
                      </td>
                      <td
                        class="align-middle small py-3"
                        style="max-width: 400px; line-height: 1.4"
                      >
                        {{ log.description }}
                      </td>
                    </tr>

                    <tr v-if="logs.length === 0">
                      <td colspan="4" class="text-center py-5">
                        <b-icon
                          icon="inbox"
                          font-scale="3"
                          class="text-light mb-2"
                        ></b-icon>
                        <p class="text-muted">
                          Selecione um período para visualizar os logs.
                        </p>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </b-overlay>
          </b-card>
        </b-col>
      </b-row>
    </b-container>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import DateFormat from "../utils/dateFormat";
import NavBarVue from "@/components/NavBar";
import exportFromJSON from "export-from-json";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
pdfMake.vfs = pdfFonts.pdfMake.vfs;

export default {
  name: "SystemLogsView",
  components: { NavBarVue },
  data: () => ({
    fromDate: "",
    toDate: "",
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "logs", "company"]),
  },

  methods: {
    getSystemLogs() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .get(
          `/api/logs/${this.user.companyId}?from=${this.fromDate}&to=${this.toDate}`
        )
        .then((res) => {
          this.$store.commit("SET_LOGS", res.data.result);
        })
        .finally(() => {
          this.$store.commit("LOADING_STATUS", false);
        });
    },

    formatDate(date) {
      return DateFormat.formatDate(date);
    },
    formatTime(date) {
      return new Date(date).toLocaleTimeString("pt-PT", {
        hour: "2-digit",
        minute: "2-digit",
      });
    },

    getActionVariant(action) {
      const a = action;
      if (a.includes("login")) return "soft-info";
      if (a.includes("delete") || a.includes("remover")) return "soft-danger";
      if (a.includes("update") || a.includes("editar")) return "soft-warning";
      if (a.includes("create") || a.includes("cadastro")) return "soft-success";
      return "light";
    },

    downloadSystemLogsPDF() {
      const body = this.logs.map((log) => [
        { text: DateFormat.formatDate(log.createdAt), fontSize: 8 },
        { text: log.userName, fontSize: 8 },
        { text: log.action, fontSize: 8 },
        { text: log.description, fontSize: 7 },
      ]);

      const docDefinition = {
        content: [
          {
            text: "MBR MICROCRÉDITO - RELATÓRIO DE AUDITORIA",
            style: "header",
          },
          {
            text: `Período: ${this.fromDate || "Início"} até ${
              this.toDate || "Hoje"
            }`,
            margin: [0, 5, 0, 15],
            fontSize: 9,
          },
          {
            table: {
              headerRows: 1,
              widths: ["auto", "auto", "auto", "*"],
              body: [
                [
                  { text: "Data", style: "tableHeader" },
                  { text: "Utilizador", style: "tableHeader" },
                  { text: "Ação", style: "tableHeader" },
                  { text: "Descrição", style: "tableHeader" },
                ],
                ...body,
              ],
            },
            layout: "lightHorizontalLines",
          },
        ],
        styles: {
          header: { fontSize: 14, bold: true, color: "#009640" },
          tableHeader: {
            bold: true,
            fontSize: 9,
            color: "white",
            fillColor: "#009640",
          },
        },
      };
      pdfMake.createPdf(docDefinition).open();
    },

    downloadSystemLogsExcel() {
      const data = this.logs.map((log) => ({
        Data: DateFormat.formatDate(log.createdAt),
        Utilizador: log.userName,
        "Acção": log.action,
        "Descrição": log.description,
      }));
      exportFromJSON({
        data,
        fileName: "Logs_MBR_Auditoria",
        exportType: "xls",
      });
    },
  },
};
</script>

<style scoped>
.text-mbr-green {
  color: #009640 !important;
}
.bg-mbr-green {
  background-color: #009640 !important;
}
.bg-mbr-light {
  background-color: #f0f9f4;
}

.btn-mbr-green {
  background-color: #009640;
  color: white;
  border: none;
  transition: all 0.3s;
}
.btn-mbr-green:hover {
  background-color: #007a33;
  transform: translateY(-1px);
}

/* VARIANTES DE BADGE SUAVES */
.badge-soft-info {
  background-color: #e0f2fe;
  color: #0369a1;
}
.badge-soft-success {
  background-color: #dcfce7;
  color: #15803d;
}
.badge-soft-warning {
  background-color: #fef9c3;
  color: #a16207;
}
.badge-soft-danger {
  background-color: #fee2e2;
  color: #b91c1c;
}

.font-weight-500 {
  font-weight: 500;
}

.table-hover tbody tr:hover {
  background-color: rgba(0, 150, 64, 0.02);
}
</style>
